<p>Правильна кваліфікація критично важлива, адже від неї залежить суворість відповідальності.</p>
<table>
<thead><tr><th>Критерій</th><th>СЗЧ, ст. 407</th><th>Дезертирство, ст. 408</th></tr></thead>
