        html: `<p>Обовʼязковий військовий облік стосується <strong>лише жінок, які здобули медичну або фармацевтичну освіту</strong> і придатні до служби за віком (18–60 років) та станом здоровʼя. Це правило діє <strong>з 1 жовтня 2023 року</strong>.</p>
<p>Ідеться про лікарок усіх спеціальностей, стоматологинь, медсестер, акушерок, фармацевток і провізорок. <strong>Облік не залежить від того, чи працює жінка за фахом</strong> — значення має сам диплом.</p>
<p>Жінки інших професій, споріднених із військово-обліковими спеціальностями, можуть стати на облік <strong>добровільно</strong>. Обовʼязку в них немає.</p>`,
