<li><b>Призначено повторний огляд.</b> Це окремий механізм: повторний огляд призначають після тимчасової непридатності, щоб оцінити результат лікування. Контрольний огляд — інша річ, його проводить вища комісія для перевірки вже ухваленого висновку. Обидва розібрані у статті про <a href="/blog/vlk-povtornyy-kontrolnyy-ohlyad/">повторний і контрольний огляд ВЛК</a>.</li>
