        html: `<p>У розмовах про ВЛК слова «повторний» і «контрольний» огляд вживають як синоніми, хоча це різні процедури з різними підставами та наслідками.</p>
<p><strong>Повторний огляд</strong> проходить особа, якій раніше визначили тимчасову непридатність із відстрочкою для лікування. Це планова процедура: після завершення строку лікування комісія оцінює, чи змінився стан здоров’я.</p>
<p><strong>Контрольний огляд</strong> призначає вища за рівнем комісія, коли перевіряє обґрунтованість висновку нижчої. Це елемент внутрішнього контролю системи військово-лікарської експертизи, і він може бути ініційований як за скаргою особи, так і з ініціативи самої комісії.</p>
<p>Розуміти різницю важливо: від неї залежить, куди звертатися і на що посилатися. Загальний порядок ми розбираємо в матеріалі про <a href="/blog/vlk-oskarzhennya/">оскарження висновку ВЛК</a>.</p>`,
