        html: `<p>Обов’язок вести військовий облік покладено на <b>всіх роботодавців</b> — і юридичних осіб, і фізичних осіб-підприємців, якщо в них є наймані працівники з числа призовників, військовозобов’язаних або резервістів.</p>
<p>Розмір бізнесу значення не має. ФОП з одним найманим працівником має ті самі базові обов’язки, що й велике підприємство, — різниця лише в обсязі документообігу та у вимозі призначати окрему відповідальну особу, яка залежить від кількості працівників на обліку.</p>
<p>Відповідальність за організацію обліку несе керівник. Це один із тих обов’язків, за який штрафують персонально, — як і за неподання відомостей про <a href="/blog/kintsevyy-benefitsiarnyy-vlasnyk/">кінцевого бенефіціарного власника</a>.</p>`,
