        html: `<p>Це найважливіше практичне питання для більшості родин.</p>
<p>За зниклим безвісти військовослужбовцем <b>зберігається</b> грошове забезпечення, і воно виплачується членам сім’ї в порядку, встановленому законодавством. Особа вважається такою, що продовжує проходити службу.</p>
<p>Ключове: статус зниклого безвісти <b>не є підставою</b> для виплати одноразової грошової допомоги у зв’язку із загибеллю — така допомога пов’язана з фактом смерті. Про виплати, пов’язані з пораненням і загибеллю, ми пишемо у матеріалі про <a href="/blog/vyplaty-poranenym-simyam/">виплати пораненим і сім’ям</a>.</p>
<p>Найчастіша проблема родин — не відмова у виплатах, а <b>зупинка нарахувань</b> через неоформлений належним чином статус або через розбіжності в документах військової частини. Тому оформлення статусу і є першочерговою дією.</p>`,
