        html: `<p>Так. Поширене уявлення, що воєнний стан скасовує відпустки, помилкове. Право на відпустку зберігається, хоча порядок її надання відрізняється від мирного часу.</p>
<p>Головна відмінність — <b>прив’язка до оперативної обстановки</b>. Надання відпустки залежить не лише від наявності підстав у військовослужбовця, а й від можливостей частини. Тому право на відпустку не тотожне праву піти у відпустку в конкретну обрану дату.</p>
<p>Це створює простір для зловживань — і водночас для правомірних відмов. Розрізняти їх і є основним практичним завданням.</p>`,
