        id: "s2",
        h2: "Щорічна основна відпустка",
        html: `<p>Щорічна основна відпустка надається військовослужбовцям, які проходять службу, зокрема й в умовах воєнного стану. Її тривалість під час воєнного стану обмежена законом і менша за звичайну.</p>
<p>Що варто знати:</p>
<ul>
<li>час, потрібний для проїзду до місця проведення відпустки й назад, до тривалості самої відпустки за загальним правилом не зараховується;</li>
<li>відпустка може надаватися частинами;</li>
<li>невикористана відпустка не «згоряє» безслідно — питання компенсації вирішується при звільненні;</li>
<li>за час відпустки зберігається грошове забезпечення.</li>
</ul>
<p>Оскільки норми щодо тривалості відпусток у період воєнного стану неодноразово змінювалися, конкретну кількість днів варто звіряти з чинною редакцією закону на момент подання рапорту.</p>`,
