        h2: "Механізм двох згод",
        html: `<p>Це головна практична перешкода, про яку варто знати заздалегідь.</p>
<p>Переведення потребує узгодженої волі: командир частини, звідки переводять, має погодитися відпустити, а командир частини, куди переводять, — прийняти. Кадрове рішення ухвалює уповноважений орган, але без цих двох позицій воно фактично не готується.</p>
<p>Звідси практична послідовність, яка реально працює:</p>
<ol>
<li>спершу з’ясувати наявність вакантної посади в бажаній частині;</li>
<li>отримати попередню позицію приймаючої сторони;</li>
<li>і лише потім подавати рапорт за місцем служби.</li>
</ol>
<p>Зворотний порядок — подати рапорт «у нікуди» — зазвичай закінчується відмовою з мотивуванням про відсутність підстав, після чого повторне звернення сприймається гірше.</p>`,
